package users

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"time"
)

var ErrUserNotFound = errors.New("user not found")
var ErrUserExists = errors.New("user exists")
var ErrBadUserName = errors.New("bad user name")
var ErrEmptyToken = errors.New("empty token")

type User struct {
	Name      string    `json:"name"`
	LinuxUser string    `json:"linux_user"`
	ChatID    string    `json:"chat_id"`
	TokenHash string    `json:"token_hash"`
	CreatedAt time.Time `json:"created_at"`
}

var nameRE = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,39}$`)

type Store struct {
	mu    sync.Mutex
	base  string
	path  string
	users []User
}

func Open(base string) (*Store, error) {
	if err := os.MkdirAll(base, 0o700); err != nil {
		return nil, err
	}
	s := &Store{
		base:  base,
		path:  filepath.Join(base, "users.json"),
		users: []User{},
	}
	b, err := os.ReadFile(s.path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return s, nil
		}
		return nil, err
	}
	var users []User
	if err := json.Unmarshal(b, &users); err != nil {
		return nil, fmt.Errorf("users: read %s: %w", s.path, err)
	}
	if users == nil {
		users = []User{}
	}
	s.users = users
	return s, nil
}

func (s *Store) Base() string {
	return s.base
}

func (s *Store) Add(u User) error {
	if !nameRE.MatchString(u.Name) {
		return ErrBadUserName
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, x := range s.users {
		if x.Name == u.Name {
			return ErrUserExists
		}
	}
	s.users = append(s.users, u)
	return s.write()
}

func (s *Store) Get(name string) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, u := range s.users {
		if u.Name == name {
			return u, nil
		}
	}
	return User{}, ErrUserNotFound
}

func (s *Store) List() []User {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]User, len(s.users))
	copy(out, s.users)
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func (s *Store) SetToken(name, token string) error {
	token = strings.TrimSpace(token)
	s.mu.Lock()
	defer s.mu.Unlock()
	idx := -1
	for i, u := range s.users {
		if u.Name == name {
			idx = i
			break
		}
	}
	if idx < 0 {
		return ErrUserNotFound
	}
	if token == "" {
		return ErrEmptyToken
	}
	s.users[idx].TokenHash = TokenHash(token)
	return s.write()
}

func TokenHash(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

func (s *Store) write() error {
	sort.Slice(s.users, func(i, j int) bool { return s.users[i].Name < s.users[j].Name })
	b, err := json.MarshalIndent(s.users, "", "  ")
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(s.base, "users-*.tmp")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	if _, err := tmp.Write(b); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return err
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpName)
		return err
	}
	if err := os.Rename(tmpName, s.path); err != nil {
		os.Remove(tmpName)
		return err
	}
	return nil
}

