package users

import (
	"crypto/subtle"
	"strings"
)

// Lookup resolves a bearer token to the user it belongs to.
//
// The token is trimmed and, if it is empty, never authorizes. A non-empty
// adminToken enables the operator path: an exact constant-time match returns
// the zero User and true, marking the operator. Otherwise the trimmed token is
// hashed and compared in constant time against each stored TokenHash in name
// order.
func (s *Store) Lookup(token, adminToken string) (User, bool) {
	t := strings.TrimSpace(token)
	if t == "" {
		return User{}, false
	}
	if adminToken != "" && subtle.ConstantTimeCompare([]byte(t), []byte(adminToken)) == 1 {
		return User{}, true
	}
	h := TokenHash(t)
	for _, u := range s.List() {
		if subtle.ConstantTimeCompare([]byte(h), []byte(u.TokenHash)) == 1 {
			return u, true
		}
	}
	return User{}, false
}

